%%================================
%%  File
%%================================
enc_File(Val) ->
    enc_File(Val, [<<48>>]).

enc_File(Val, TagIn) ->
   {EncBytes,EncLen} = 'enc_File_components'(Val,[],0),
   encode_tags(TagIn, EncBytes, EncLen).

'enc_File_components'([], AccBytes, AccLen) -> 
   {lists:reverse(AccBytes),AccLen};

'enc_File_components'([H|T],AccBytes, AccLen) ->
   {EncBytes,EncLen} = 'enc_File_SEQOF'(H, []),
   'enc_File_components'(T,[EncBytes|AccBytes], AccLen + EncLen).




%%================================
%%  File_SEQOF
%%================================
enc_File_SEQOF(Val, TagIn) ->
      {EncBytes,EncLen} = case element(1,Val) of
      doNotCreate ->
         encode_null(element(2,Val), [<<128>>]);
      fileDescriptor ->
         'enc_Fcp'(element(2,Val), [<<161>>]);
      fillFileOffset ->
         encode_integer(element(2,Val), [<<130>>]);
      fillFileContent ->
         encode_restricted_string(element(2,Val), [<<131>>]);
      Else -> 
         exit({error,{asn1,{invalid_choice_type,Else}}})
