dec_File(Tlv, TagIn) ->
   %%-------------------------------------------------
   %% decode tag and length 
   %%-------------------------------------------------
Tlv1 = match_tags(Tlv, TagIn),
['dec_File_SEQOF'(V1, []) || V1 <- Tlv1].


'dec_File_SEQOF'(Tlv, TagIn) ->
Tlv1 = match_tags(Tlv, TagIn),
case (case Tlv1 of [CtempTlv1] -> CtempTlv1; _ -> Tlv1 end) of

%% 'doNotCreate'
    {131072, V1} -> 
        {doNotCreate, decode_null(V1, [])};


%% 'fileDescriptor'
    {131073, V1} -> 
        {fileDescriptor, 'dec_Fcp'(V1, [])};


%% 'fillFileOffset'
    {131074, V1} -> 
        {fillFileOffset, begin
Val1 = decode_integer(V1, []),
if 0 =< Val1, Val1 =< 65535 ->
Val1;
true ->
exit({error,{asn1,bad_range}})
end
end};


%% 'fillFileContent'
    {131075, V1} -> 
        {fillFileContent, decode_octet_string(V1, [])};

      Else -> 
         {asn1_ExtAlt,ber_encode(Else)}
   end
.


